"""Stage 6: Markdown tables for notes/models.md (generated by ml/run_stage6.py)."""

from __future__ import annotations

from pathlib import Path

import pandas as pd

from baselines import LABELS_UK

FAMILY_UK = {"lr": "логістична регресія", "rf": "Random Forest", "hgb": "HistGradientBoosting", "lgbm": "LightGBM"}
POLICY_UK = {"topk": "top-k % тестів", "budget": "бюджет часу", "threshold": "поріг τ"}


def label(method: str) -> str:
    if method in LABELS_UK:
        return LABELS_UK[method]
    base, _, suffix = method.partition("@")
    fam, _, cost = base.partition("/")
    name = FAMILY_UK.get(fam, fam)
    if cost:
        name += ", p / тривалість"
    if suffix:
        name += f" [{suffix}]"
    return name


def agg(df: pd.DataFrame, cols: list[str]) -> pd.DataFrame:
    """Mean and std over seeds per method (baselines have one row)."""
    g = df.groupby("method", sort=False)
    mean = g[cols].mean()
    std = g[cols].std(ddof=1).fillna(0.0)
    n = g.size().rename("seeds")
    return mean, std, n


def ms(mean: float, std: float, digits: int = 3, pct: bool = False) -> str:
    if pct:
        mean, std = 100 * mean, 100 * std
        digits = 1
    if std > 0:
        return f"{mean:.{digits}f} ± {std:.{digits}f}"
    return f"{mean:.{digits}f}"


def table(df: pd.DataFrame, methods: list[str], spec: list[tuple[str, str, bool]]) -> str:
    cols = [c for c, _, _ in spec]
    mean, std, n = agg(df[df["method"].isin(methods)], cols)
    rows = []
    for m in methods:
        if m not in mean.index:
            continue
        r = {"метод": label(m), "seed": int(n[m])}
        for c, title, pct in spec:
            r[title] = ms(mean.at[m, c], std.at[m, c], pct=pct)
        rows.append(r)
    return pd.DataFrame(rows).to_markdown(index=False)


def write(out: Path, ds, metrics_df, tuning, variants, chosen_variant, policies, fixed, cards, main_family, calib, single_auc) -> None:
    fams = list(cards)
    baselines = ["random", "shortest", "criticality", "fail_rate", "covers", "recent", "combined", "oracle"]
    order = baselines[:-1] + fams + [baselines[-1]]
    a, b = ds.val_range
    red = int(metrics_df["red_commits"].iloc[0])
    L = [
        "# Етап 6: результати на val (згенеровано ml/run_stage6.py)",
        "",
        f"Val — коміти {a}–{b - 1} ({b - a} комітів, {red} «червоних»). Test-частина {ds.test_range[0]}–{ds.test_range[1] - 1} відкинута одразу після читання й не оцінювалася.",
        "Моделі навчено на комітах 0–{0}; для стохастичних моделей — середнє ± std за 10 seed, детерміновані — один seed.".format(ds.train_range[1] - 1),
        "APFD/APFDc — середнє по «червоних» комітах (fault = тест, що впав); «нові» — лише коміти з новими падіннями.",
        "Нічиї — випадкові (20 перестановок, random — 200; спільні ключі для всіх методів).",
        "",
        "## 1. Пріоритизація",
        "",
        table(metrics_df, order, [
            ("apfd", "APFD", False), ("apfd_median", "APFD (медіана)", False), ("apfdc", "APFDc", False),
            ("apfd_new", "APFD нові", False), ("apfd_repeat", "APFD повторні", False), ("apfd_defect", "APFD (дефекти)", False),
            ("ttd_share", "час до 1-го падіння, частка", False),
        ]),
        "",
        "## 2. Відбір top-k % тестів: частка виявлених «червоних» комітів (рівень коміту), %",
        "",
        table(metrics_df, order, [(f"top{k}_recall_commit", f"top-{k} %", True) for k in (10, 20, 30, 50)]
              + [(f"top{k}_recall_commit_new", f"top-{k} % (нові)", True) for k in (10, 30)]),
        "",
        "## 3. Відбір top-k % тестів: частка тестів, що впали, які потрапили до відбору (рівень тестів), %",
        "",
        table(metrics_df, order, [(f"top{k}_recall_test", f"top-{k} %", True) for k in (10, 20, 30, 50)]
              + [(f"top{k}_recall_test_new", f"top-{k} % (нові)", True) for k in (10, 30)]),
        "",
        "## 4. Бюджет часу B % (відбір за прогнозною тривалістю), %",
        "",
        "Recall — частка «червоних» комітів; час — фактична частка повного прогону (середнє по всіх комітах val і максимум); «номінальний» — частка за прогнозними тривалостями.",
        "",
        table(metrics_df, order, sum([[ (f"bud{k}_recall_commit", f"B={k}: recall", True), (f"bud{k}_time", f"B={k}: час", True),
                                         (f"bud{k}_time_max", f"B={k}: час max", True)] for k in (10, 30, 50)], [])),
        "",
        "## 5. Recall за часом у режимі пріоритизації (перше падіння завершилося до B % фактичного часу), %",
        "",
        table(metrics_df, order, [(f"recall_time_{k}", f"{k} % часу", True) for k in (10, 20, 30, 50)]),
        "",
    ]

    # Combined heuristic variants.
    v = variants[["variant", "description", "apfd", "apfdc", "apfd_new", "apfd_repeat", "top30_recall_commit", "selected"]].copy()
    v = v.rename(columns={"variant": "варіант", "description": "ключі", "top30_recall_commit": "recall@top-30 %", "selected": "обрано"})
    L += ["## 6. Варіанти комбінованої евристики (вибір на val за APFD)", "", v.round(3).to_markdown(index=False), "",
          f"Обрано: `{chosen_variant}`.", ""]

    # Tuning.
    rows = []
    for fam in fams:
        t = tuning[tuning["family"] == fam]
        sel = t[t["selected"]].iloc[0]
        rows.append({"модель": FAMILY_UK[fam], "конфігурацій": len(t), "APFD (мін–макс по сітці)": f"{t['apfd'].min():.3f}–{t['apfd'].max():.3f}",
                     "обрано": sel["params_json"], "APFD обраної": f"{sel['apfd']:.3f}",
                     "seed": "інваріантна" if cards[fam]["seed_invariant"] else f"{len(cards[fam]['seeds'])} seed"})
    L += ["## 7. Підбір гіперпараметрів (seed 20261117, навчання 0–{0}, критерій — APFD на val)".format(ds.train_range[1] - 1), "",
          pd.DataFrame(rows).to_markdown(index=False), "", f"Основна модель (найкраще середнє APFD за seed): **{FAMILY_UK[main_family]}**.", ""]

    all_policies = policies
    policies = policies[policies["criterion"] == "commit"]

    # Policies.
    pol = policies.groupby(["method", "policy", "target"], sort=False)[["setting", "recall_commit", "recall_commit_new", "tests", "time", "time_max", "time_red", "pred_time"]].agg(["mean", "std"])
    prow = []
    pol_methods = ["recent", "covers", "combined"] + fams + [f"{f}/cost" for f in fams] + [f"{f}@no_commit_chg" for f in fams]
    for (m, p, t), r in pol.iterrows():
        if m not in pol_methods:
            continue
        g = lambda c, pct=True: ms(r[(c, "mean")], 0 if pd.isna(r[(c, "std")]) else r[(c, "std")], pct=pct)
        setting = r[("setting", "mean")]
        sd = 0.0 if pd.isna(r[("setting", "std")]) else r[("setting", "std")]
        if p == "topk":
            s = f"{setting * 36:.1f} ± {sd * 36:.1f} тестів" if sd > 0 else f"{round(setting * 36)} тестів"
        elif p == "budget":
            s = f"B = {100 * setting:.1f} ± {100 * sd:.1f} %" if sd > 0 else f"B = {100 * setting:.0f} %"
        else:
            s = f"τ = {setting:.3f} ± {sd:.3f}" if sd > 0 else f"τ = {setting:.3f}"
        prow.append({"метод": label(m), "політика": POLICY_UK[p], "ціль": f"{100 * t:.0f} %", "параметр": s,
                     "recall комітів": g("recall_commit"), "recall (нові)": g("recall_commit_new"), "тестів": g("tests"),
                     "час, сер.": g("time"), "час, max": g("time_max"), "час «черв.»": g("time_red"), "час номін.": g("pred_time")})
    prow.sort(key=lambda r: (pol_methods.index(next(m for m in pol_methods if label(m) == r["метод"])),))
    L += ["## 8. Політики відбору: найдешевше налаштування з recall комітів ≥ цілі (вибрано й оцінено на val — in-sample), %", "",
          "Час — фактична частка повного прогону (`eval_duration_ms`), середнє по всіх 108 комітах val, максимум і середнє по «червоних»; «номін.» — за прогнозними тривалостями. H1: recall ≥ 90 % за ≤ 30 % часу.", "",
          pd.DataFrame(prow).to_markdown(index=False), ""]

    # Control: commit-level chg_ removed.
    crow = []
    for fam in fams:
        main = metrics_df[metrics_df["method"] == fam]
        ctrl = metrics_df[metrics_df["method"] == f"{fam}@no_commit_chg"]
        pm = policies[(policies["method"] == fam) & (policies["policy"] == "threshold") & (policies["target"] == 0.9)]
        pc = policies[(policies["method"] == f"{fam}@no_commit_chg") & (policies["policy"] == "threshold") & (policies["target"] == 0.9)]
        crow.append({
            "модель": FAMILY_UK[fam],
            "APFD main": f"{main['apfd'].mean():.3f}", "APFD без комітних chg_": f"{ctrl['apfd'].mean():.3f}", "Δ APFD": f"{main['apfd'].mean() - ctrl['apfd'].mean():+.3f}",
            "Δ APFD нові": f"{main['apfd_new'].mean() - ctrl['apfd_new'].mean():+.3f}",
            "τ@90 %: час main": f"{100 * pm['time'].mean():.1f}", "τ@90 %: час контроль": f"{100 * pc['time'].mean():.1f}",
            "τ@90 %: Δ час, п. п.": f"{100 * (pm['time'].mean() - pc['time'].mean()):+.1f}",
            "ROC-AUC main / контроль": f"{main['roc_auc'].mean():.3f} / {ctrl['roc_auc'].mean():.3f}",
        })
    L += ["## 9. Контроль артефакту форми діфа: та сама конфігурація без 16 комітних `chg_` (`no_commit_chg`)", "",
          pd.DataFrame(crow).to_markdown(index=False), ""]

    # Cost-aware ranking.
    krow = []
    for fam in fams:
        p_ = metrics_df[metrics_df["method"] == fam]
        c_ = metrics_df[metrics_df["method"] == f"{fam}/cost"]
        krow.append({"модель": FAMILY_UK[fam],
                     "APFD: p / p÷t": f"{p_['apfd'].mean():.3f} / {c_['apfd'].mean():.3f}",
                     "APFDc: p / p÷t": f"{p_['apfdc'].mean():.3f} / {c_['apfdc'].mean():.3f}",
                     "B=30 %: recall p / p÷t": f"{100 * p_['bud30_recall_commit'].mean():.1f} / {100 * c_['bud30_recall_commit'].mean():.1f}",
                     "B=30 %: час p / p÷t": f"{100 * p_['bud30_time'].mean():.1f} / {100 * c_['bud30_time'].mean():.1f}",
                     "B=10 %: recall p / p÷t": f"{100 * p_['bud10_recall_commit'].mean():.1f} / {100 * c_['bud10_recall_commit'].mean():.1f}"})
    L += ["## 10. Ранжування з урахуванням вартості: p проти p / `meta_duration_mean`", "", pd.DataFrame(krow).to_markdown(index=False), ""]

    # Diagnostics.
    L += ["## 11. Діагностика класифікатора на val (не критерій вибору)", "",
          table(metrics_df, fams + [f"{f}@no_commit_chg" for f in fams],
                [("roc_auc", "ROC-AUC", False), ("pr_auc", "PR-AUC", False), ("brier", "Brier", False), ("f1_at_0_5", "F1 (поріг 0,5)", False), ("mean_p", "середня p", False)]),
          "", f"Частка позитивів на val: {ds.meta['splits']['val']['positive_share']:.4f}. Моделі з `class_weight`/`scale_pos_weight` мають завищені ймовірності, тож їхній Brier гірший незалежно від якості ранжування.", "",
          "ROC-AUC окремих ознак на val: " + "; ".join(f"`{k}` {v:.3f}" for k, v in single_auc.items()) + ".", "",
          f"Калібрування основної моделі ({FAMILY_UK[main_family]}, seed 20261117) на val: Brier без калібрування {calib['brier_raw']:.4f}; "
          f"sigmoid {calib['brier_sigmoid_in_sample']:.4f} (in-sample) / {calib['brier_sigmoid_cross_fitted']:.4f} (перехресно між половинами val); "
          f"isotonic {calib['brier_isotonic_in_sample']:.4f} / {calib['brier_isotonic_cross_fitted']:.4f}. Обрано: {calib['chosen_method']}. "
          "In-sample значення оптимістичні.", ""]
    L += first_exposure_tables(metrics_df, all_policies, order, fams)
    (out / "tables.md").write_text("\n".join(L), encoding="utf-8")


def first_exposure_tables(metrics_df, policies, order, fams) -> list[str]:
    """Selection recall at the defect level and at first exposure (notes/decisions.md, p. 7)."""
    L = ["## 12. Відбір на рівні дефектів і першої появи дефекту", "",
         "Пари (коміт, дефект) — відкритий дефект із хоча б одним позитивом у коміті; перша поява — пара в коміті внесення дефекту "
         f"(val: {int(metrics_df['defect_pairs'].iloc[0])} пар, {int(metrics_df['first_pairs'].iloc[0])} перших появ). "
         "Recall — частка пар, для яких відібрано хоча б один тест, що падає через цей дефект.", "",
         "### 12.1. Фіксовані бюджети B % (прогнозний час), %", "",
         table(metrics_df, order, sum([[(f"bud{k}_recall_commit", f"B={k}: коміти", True), (f"bud{k}_recall_defect", f"B={k}: дефекти", True),
                                        (f"bud{k}_recall_first", f"B={k}: перша поява", True)] for k in (10, 30, 50)], [])),
         "",
         "### 12.2. Бюджет часу: найдешевше B з recall ≥ 90 % за кожним критерієм (вибрано й оцінено на val — in-sample), %", "",
         "Час — фактична частка повного прогону, середнє по всіх комітах val. H1: recall ≥ 90 % за ≤ 30 % часу.", ""]
    rows = []
    for m in ["recent", "covers", "combined"] + fams:
        r = {"метод": label(m)}
        for crit, title in (("commit", "коміти"), ("defect", "дефекти"), ("first", "перша поява")):
            p = policies[(policies["method"] == m) & (policies["criterion"] == crit) & (policies["policy"] == "budget") & (policies["target"] == 0.9)]
            if p.empty:
                r[f"{title}: B"] = r[f"{title}: час"] = "не досягає"
                continue
            sd = lambda c: 0.0 if len(p) < 2 else p[c].std(ddof=1)
            r[f"{title}: B"] = ms(p["setting"].mean(), sd("setting"), pct=True)
            r[f"{title}: час"] = ms(p["time"].mean(), sd("time"), pct=True)
        rows.append(r)
    L += [pd.DataFrame(rows).to_markdown(index=False), ""]

    # The stage 6 selection rule (cheapest mean actual time at the 0.90 target among the policies on p
    # and on p / duration) applied with the first-exposure criterion.
    L += ["### 12.3. Політики моделей за критерієм першої появи (ціль 90 %; вибрано й оцінено на val — in-sample), %", ""]
    rows = []
    for fam in fams:
        for m in (fam, f"{fam}/cost"):
            for pol in ("topk", "budget", "threshold"):
                p = policies[(policies["method"] == m) & (policies["criterion"] == "first") & (policies["policy"] == pol) & (policies["target"] == 0.9)]
                if p.empty:
                    continue
                sd = lambda c: 0.0 if len(p) < 2 else p[c].std(ddof=1)
                rows.append({"метод": label(m), "політика": POLICY_UK[pol],
                             "перша поява": ms(p["recall_first"].mean(), sd("recall_first"), pct=True),
                             "коміти": ms(p["recall_commit"].mean(), sd("recall_commit"), pct=True),
                             "час, сер.": ms(p["time"].mean(), sd("time"), pct=True), "час, max": ms(p["time_max"].mean(), sd("time_max"), pct=True),
                             "час «черв.»": ms(p["time_red"].mean(), sd("time_red"), pct=True)})
    L += [pd.DataFrame(rows).to_markdown(index=False), ""]
    return L
